import React, { useState } from 'react';
import './styles.css';

function parseLines(text) {
  const lines = text.split('\n');
  const records = [];
  lines.forEach((raw) => {
    if (raw.trim() === '') return;
    const i = raw.indexOf(',');
    if (i === -1) return;
    const name = raw.slice(0, i).trim();
    const scoreText = raw.slice(i + 1).trim();
    if (name === '') return;
    if (scoreText === '') return;
    const score = Number(scoreText);
    if (Number.isNaN(score)) return;
    if (score < 0 || score > 100) return;
    records.push({ name, score });
  });
  return records;
}

export default function App() {
  const [text, setText] = useState('');
  const [records, setRecords] = useState([]);
  const [analyzed, setAnalyzed] = useState(false);

  const handleAnalyze = () => {
    setRecords(parseLines(text));
    setAnalyzed(true);
  };

  return (
    <main className="app">
      <h1>成绩文本分析器</h1>
      <textarea
        data-testid="score-input"
        className="score-input"
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="每行一条：姓名,分数"
        rows={6}
      />
      <div className="actions">
        <button data-testid="analyze-button" type="button" onClick={handleAnalyze}>
          分析
        </button>
      </div>
      {analyzed && (
        <table data-testid="valid-table" className="valid-table">
          <thead>
            <tr>
              <th>姓名</th>
              <th>分数</th>
            </tr>
          </thead>
          <tbody>
            {records.map((r, idx) => (
              <tr key={idx}>
                <td>{r.name}</td>
                <td>{r.score}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </main>
  );
}

